-  handleContent(contentType, windowContext, request) {
-    if (contentType != "x-application-imapfolder") {
-      throw Components.Exception(
-        `Won't handle ${contentType}`,
-        Cr.NS_ERROR_WONT_HANDLE_CONTENT
-      );
