-  constructor(tokens) {
-    this.attributes = {};
-
-    // The first two tokens are ["*", "STATUS"], the last token is the attribute
-    // list, the middle part is the mailbox name.
-    this.attributes.mailbox = unwrapString(tokens[2]);
